":32},"shapes":[{"type":"circle","x":20,"y":20,"r":11,"color":"#ffffff"},{"type":"circle","x":40,"y":15,"r":14,"color":"#ffffff"},{"type":"circle","x":60,"y":20,"r":11,"color":"#ffffff"},{"type":"rect","x":9,"y":20,"w":62,"h":11,"color":"#ffffff"},{"type":"rect","x":9,"y":27,"w":62,"h":4,"color":"#dfe9f5"},{"type":"circle","x":36,"y":10,"r":4,"color":"#f4f9ff"}],"layer":"back"}],"rooms":[{"id":"peppas-hill","name":"Peppa's Hill","objective":"Run down the hill to find some muddy puddles","layout":["..................................................................","..................................................................","..................................................................","..................................................................","..................................................................","..................................................................","..................................................................","..................................................................","..................................................................","..............####...............=====............................","...........##########................................###..........","..S..a..################..1...........4.C..^^..2..########.....E..","#############################..############################...####","#############################..############################...####"],"isBossRoom":false,"exit":{"toRoom":"the-muddy-fields"},"props":[{"prop":"cloud","col":4,"row":2},{"prop":"cloud","col":30,"row":1},{"prop":"hill-house","col":14,"row":8},{"prop":"family-car","col":18,"row":9},{"prop":"flowers","col":9,"row":10},{"prop":"flowers","col":21,"row":10},{"prop":"lollipop-tree","col":24,"row":11},{"prop":"fence","col":34,"row":11},{"prop":"mud-puddle","col":41,"row":11},{"prop":"lollipop-tree","col":48,"row":11}]},{"id":"the-muddy-fields","name":"The Muddy Fields","objective":"Splash across the muddy fields","layout":["......................................................................","......................................................................","......................................................................","......................................................................","......................................................................","......................................................................","......................................................................","..........................=====.......................................","......................................................................",".......=====.........................................###..............","......................####........................######..............","..S.b.........3.......####......1..C..^^......4###########..2......E..","#################...######################...#########################","#################...######################...#########################"],"isBossRoom":false,"exit":{"toRoom":"the-biggest-muddy-puddle"},"props":[{"prop":"lollipop-tree","col":0,"row":11},{"prop":"mud-puddle","col":9,"row":11},{"prop":"cloud","col":10,"row":2},{"prop":"lollipop-tree","col":20,"row":11},{"prop":"mud-puddle","col":27,"row":11},{"prop":"fence","col":36,"row":11},{"prop":"cloud","col":40,"row":1},{"prop":"mud-puddle","col":45,"row":11},{"prop":"flowers","col":58,"row":11},{"prop":"lollipop-tree","col":64,"row":11}]},{"id":"the-biggest-muddy-puddle","name":"The Biggest Muddy Puddle","objective":"Win the jumping contest against Daddy Pig","layout":["............................................","............................................","............................................","............................................","............................................","............................................","...............=====........................","............................................","..............................====..........","........=====.........=====.................","............................................","..S..........................^........B.....","############################################","############################################"],"isBossRoom":true,"exit":{"toRoom":"END"},"props":[{"prop":"lollipop-tree","col":0,"row":11},{"prop":"flowers","col":4,"row":11},{"prop":"cloud","col":6,"row":1},{"prop":"lollipop-tree","col":13,"row":11},{"prop":"fence","col":20,"row":11},{"prop":"cloud","col":26,"row":2},{"prop":"mud-puddle","col":36,"row":11},{"prop":"mud-puddle","col":40,"row":11}]}],"dialogue":{"roomIntro":[[{"speaker":"Peppa","text":"It stopped raining! Can I go out and play, please?"},{"speaker":"Peppa","text":"George, stop following me! ...Okay, you can come."}],[{"speaker":"Peppa","text":"Muddy puddles everywhere! I love jumping in muddy puddles!"},{"speaker":"Suzy Sheep","text":"Peppa! Wait for me! Sheep can jump too!"}],[{"speaker":"Peppa","text":"That's the biggest muddy puddle in the whole world!"}]],"bossIntro":[{"speaker":"Daddy Pig","text":"Ho ho! I happen to be an expert at jumping in muddy puddles."},{"speaker":"Peppa","text":"Daddy! Let's see who makes the biggest splash!"}],"bossDefeated":[{"speaker":"Daddy Pig","text":"Oh dear. I'm covered in mud! Ho ho ho!"},{"speaker":"Peppa","text":"Everyone loves jumping in muddy puddles! *snort*"}],"playerDefeated":[{"speaker":"Peppa","text":"Waaah! I'm all muddy and it's not fun anymore!"},{"speaker":"Daddy Pig","text":"Never mind, Peppa. Let's have a bath and try again."}]}},"notes":{"sourceFacts":["'Muddy Puddles' is the first episode of Peppa Pig series 1.","Peppa and her little brother George love jumping up and down in muddy puddles.","Peppa wears a red dress; George carries his toy, Mr. Dinosaur.","In the episode Daddy Pig joins in jumping in the puddles and everyone ends up muddy.","Suzy Sheep, Danny Dog and Rebecca Rabbit are Peppa's friends from the series.","Mummy Pig tells Peppa and George to put on their boots before jumping in muddy puddles.","Grandpa Pig is Peppa's grandfather; he loves boats and sailing.","Peppa's family lives in a house on top of a hill and drives a red car."],"designChoices":["Rigs are simplified fan-style pixel versions of the cast in their iconic colours (Peppa's red dress, George's blue top, Daddy Pig's glasses and teal shirt).","Daddy Pig is the boss: his big puddle jump in the episode became a jump-and-charge boss fight. He has glasses, stubble dots and a round belly.","George, Suzy Sheep, Danny Dog and Rebecca Rabbit are playful 'enemies'; Suzy, Danny and Rebecca are not in this episode.","Rebecca Rabbit is a jumper at civilian tier (HP 12, AD 1) in a green knitted jumper.","Mummy Pig (room 1) and Grandpa Pig (room 2, captain's hat) are friendly NPCs; Grandpa being out in the fields is a design choice.","Scenery props: the family house on top of the hill with the red car beside it, round trees, flower clumps, fences, muddy puddles and clouds.","Spikes stand in for prickly thistles in the grass (the engine has only spikes as a hazard).","Room order Peppa's Hill -> The Muddy Fields -> The Biggest Muddy Puddle is invented for the game.","Push, Muddy Splash and Giggle Fit are invented abilities based on Peppa's playground behaviour.","Danny Dog's orange top and Suzy's purple dress are simplified colour choices for tiny sprites."]},"createdAt":"2026-11-21T12:00:00.000Z"}$$), '2026-11-21T12:00:00.000Z'::TIMESTAMP_TZ;

